#!/usr/bin/env node
import { withSourceLinks, writeLlmsArtifacts } from "../../../scripts/docs-site/llms.mjs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { buildLlmsTxtArtifacts, buildManifest, loadDocsConfig } from "@docsfn/core";
import { FsContentProvider } from "@docsfn/provider-fs";

const here = dirname(fileURLToPath(import.meta.url));
const cwd = resolve(here, "..");
const staticDir = resolve(cwd, "static");

const config = await loadDocsConfig({ cwd });
const provider = new FsContentProvider({
  root: config.content.root || cwd,
  docsDir: config.content.docsDir,
  pagesDir: config.content.pagesDir,
  blogDir: config.content.blogDir,
  apiDir: config.content.apiDir,
  assetsDir: config.content.assetsDir,
});

const manifest = await buildManifest(provider, config);

const artifacts = buildLlmsTxtArtifacts(manifest, {
  canonicalUrl: config.site?.canonicalUrl,
  includeBlog: false,
});

artifacts.llmsTxt = withSourceLinks(artifacts.llmsTxt, manifest, "authfn", config.site?.canonicalUrl);
artifacts.llmsFullTxt = withSourceLinks(artifacts.llmsFullTxt, manifest, "authfn", config.site?.canonicalUrl);
artifacts.llmsFullTxt = artifacts.llmsFullTxt.replace("For programmatic access, prefer the MCP server\nor the structured manifest emitted alongside this file.", "For a page index, see /docs/llms.txt.");
writeLlmsArtifacts(staticDir, artifacts);
import type { DocsConfig } from "@docsfn/core";

const config: DocsConfig = {
  schemaVersion: 1,
  site: {
    title: "authfn",
    description: "Self-hosted authentication for any stack. Sessions, OTP, passwords, social OAuth, 2FA, API keys, multi-region. TypeScript, Python, and Swift SDKs.",
    basePath: "/docs",
    canonicalUrl: "https://authfn.com",
    showFooter: false,
    editLink: {
      pattern: "https://github.com/21nCo/super-functions/edit/dev/authfn/docs/{path}",
    },
  },
  compat: { preset: "none" },
  content: {
    root: ".",
    docsDir: "content/docs",
    blogDir: "content/blog",
    apiDir: "content/api",
    pagesDir: "content/pages",
    assetsDir: "static",
    metaFileName: "meta.json",
  },
  navigation: {
    topNav: [
      { label: "Docs", href: "/docs" },
      { label: "API Reference", href: "/docs/api" },
      { label: "Blog", href: "/blog" },
      {
        label: "GitHub",
        href: "https://github.com/21nCo/super-functions/tree/dev/authfn",
        external: true,
      },
    ],
    sidebars: {
      docs: { title: "Documentation", root: true, include: ["docs/**"] },
      api: { title: "API Reference", root: true, include: ["docs/api/**"] },
    },
  },
  search: {
    enabled: true,
    scopes: ["docs", "api", "blog"],
    bodyIndexing: "summary",
    routeScopeOverrides: [
      { pattern: "/docs/api", scope: "api" },
      { pattern: "/docs/api/**", scope: "api" },
    ],
  },
  auth: { enabled: false, mode: "public" },
  analytics: { enabled: false, provider: "watchfn", respectDnt: true },
};

export default config;
